const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
        AlignmentType, LevelFormat, HeadingLevel, BorderStyle, WidthType,
        ShadingType, PageNumber, Header, Footer, TabStopType, TabStopPosition } = require('docx');
const fs = require('fs');

const BRAND_GOLD = "B08D57";
const BRAND_DARK = "1F1F1F";
const BRAND_LIGHT = "F5F1EA";
const BORDER_GREY = "CCCCCC";

const border = { style: BorderStyle.SINGLE, size: 1, color: BORDER_GREY };
const borders = { top: border, bottom: border, left: border, right: border };

// Helper: paragraph
const P = (text, opts = {}) => new Paragraph({
  spacing: { before: 80, after: 80, line: 300 },
  children: [new TextRun({ text, ...opts })],
  ...opts.paragraphProps
});

// Helper: bold heading body paragraph
const H2 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  children: [new TextRun({ text })],
  spacing: { before: 280, after: 140 }
});

const H3 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_3,
  children: [new TextRun({ text })],
  spacing: { before: 200, after: 100 }
});

const Bullet = (text, level = 0) => new Paragraph({
  numbering: { reference: "bullets", level },
  spacing: { before: 40, after: 40, line: 290 },
  children: [new TextRun({ text })]
});

const BulletRich = (runs, level = 0) => new Paragraph({
  numbering: { reference: "bullets", level },
  spacing: { before: 40, after: 40, line: 290 },
  children: runs
});

// Two-column KPI table cell
const tCell = (text, opts = {}) => new TableCell({
  borders,
  width: { size: opts.width || 4680, type: WidthType.DXA },
  shading: opts.shading ? { fill: opts.shading, type: ShadingType.CLEAR } : undefined,
  margins: { top: 100, bottom: 100, left: 140, right: 140 },
  children: [new Paragraph({
    children: [new TextRun({ text, bold: opts.bold, color: opts.color, size: opts.size || 22 })]
  })]
});

// ---------- COVER ----------
const cover = [
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 2400, after: 200 },
    children: [new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, size: 32, color: BRAND_GOLD, characterSpacing: 80 })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 1600 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: BRAND_GOLD, space: 8 } },
    children: [new TextRun({ text: "Sales Partner Role Outline", italics: true, size: 24, color: BRAND_DARK })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 400, after: 100 },
    children: [new TextRun({ text: "Position Summary, Compensation, KPIs, and Mutual Expectations", size: 26, bold: true })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 2000 },
    children: [new TextRun({ text: "Prepared for: William [Last Name]", size: 22, italics: true, color: "555555" })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 100 },
    children: [new TextRun({ text: "Issued by:", size: 20, color: "777777" })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 60 },
    children: [new TextRun({ text: "Bethany [Last Name], Co-Founder & CEO", size: 22, bold: true })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 60 },
    children: [new TextRun({ text: "Eric [Last Name], Co-Founder & CFO", size: 22, bold: true })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 800 },
    children: [new TextRun({ text: "theluxoracollective.co", size: 20, color: BRAND_GOLD, italics: true })]
  }),
  new Paragraph({ children: [new TextRun({ text: "", break: 1 })], pageBreakBefore: true })
];

// ---------- BODY ----------
const body = [
  // Welcome / Overview
  new Paragraph({
    heading: HeadingLevel.HEADING_1,
    children: [new TextRun({ text: "Welcome to The Luxora Collective" })],
    spacing: { after: 160 }
  }),
  P("This document outlines the role, expectations, compensation structure, and culture you are being invited into as our first dedicated Sales Partner. It is a working framework, not a rigid contract, and is intended to set us up for a long, productive, and transparent partnership. The formal independent contractor agreement that accompanies this outline is the binding legal document; this is the plain-language version so that nothing about how we work together is hidden, vague, or assumed."),
  P("We are a startup. That means the role you step into today will not look identical to the role twelve months from now. We are growing quickly, refining as we go, and we want a teammate who sees opportunity in that, not friction."),

  // Section 1
  H2("1. Position Overview"),
  P("Title: Sales Partner (Independent Contractor)"),
  P("Reports to: Bethany [Last Name], Co-Founder & CEO; coordinates with Eric [Last Name], Co-Founder & CFO."),
  P("Primary mandate: Convert qualified inbound discovery calls into paying clients of The Luxora Collective\u2019s 90-Day Growth Engine and any related programs we offer now or in the future. Secondary mandate: Support sales-adjacent activities (follow-up, onboarding handoff, reactivation, partner outreach) when capacity allows and when not actively in a sales conversation."),
  P("Primary client profile: Independent medspa owners generating between $500K and $2M in annual revenue."),

  // Section 2
  H2("2. What We Expect of You"),

  H3("Sales Execution"),
  Bullet("Run discovery and sales calls using the established Luxora sales script and the \"feminine funnel\" framework: trust-building, emotional mirroring, permission-based transitions, soft close, and no fake urgency."),
  Bullet("Deliver the Revenue Leak Audit live on call, transition into the emotional close, and present the Market Blueprint and 90-Day Growth Engine offer with full command of the value, deliverables, and guarantee."),
  Bullet("Maintain a calendar that is open and available for sales calls Monday through Saturday, with the understanding that the bulk of calls will fall during standard business hours across Eastern, Central, and Pacific time zones."),
  Bullet("Respond to assigned leads, follow-ups, and team communication within agreed-upon response windows during your active working hours."),
  Bullet("Use only Luxora-approved communication channels (Slack internally, GoHighLevel for client touchpoints). Personal phone numbers are never shared with prospects or clients."),

  H3("Team Contribution"),
  Bullet("Pitch in on sales-adjacent tasks when not actively on calls. Examples: follow-up touches, second and third sales conversations, partner introductions, light onboarding support, and outbound calls using our internal prospecting tool. You will not be asked to do tech setup, video production, or work outside the sales function."),
  Bullet("Bring ideas to the table. We are not micromanagers, and we are not dictators. If you see a better way, say so. We will listen, weigh it, and act on it where it makes sense."),
  Bullet("Represent the Luxora brand voice on every call: warm, direct, no corporate filler, no fake urgency, and no overpromising. Our reputation is the asset we protect first."),

  H3("Conduct and Confidentiality"),
  Bullet("Treat all client information, internal documents, scripts, frameworks, prospect lists, ad creative, and CRM data as confidential and proprietary to The Luxora Collective."),
  Bullet("Operate with the same compassionate, no-nonsense energy Bethany brings to her own calls. Clients should feel the same culture from any Luxora representative they speak with."),

  // Section 3
  H2("3. What You Can Expect of Us"),
  Bullet("A product that sells. The 90-Day Growth Engine is built on real frameworks, real deliverables, and a real guarantee. You are not selling vapor."),
  Bullet("A consistent flow of inbound qualified leads through Meta ads, organic social content (Viral Coach), partnership referrals, and our internal prospecting tool. We currently average three to six sales calls per week and are scaling this aggressively."),
  Bullet("A complete sales toolkit on day one: discovery call script, Revenue Leak Audit framework, branded sales documents, Market Blueprint preview reports, our market intelligence tool, KPI calculator, and the full library of program deliverables."),
  Bullet("Shadowing and onboarding directly with Bethany during your first weeks so you absorb the voice, the flow, and the close before you run calls solo."),
  Bullet("Direct access to leadership. Both Bethany and Eric are reachable, responsive, and open. We solve problems together and we celebrate wins together."),
  Bullet("Clear, fair compensation that is honored. We will not move the goalposts on commission. If you make significant money, that means the company is making significant money, and we are aligned, not threatened, by that."),
  Bullet("A path forward. As Luxora grows, this role can grow with it: senior sales lead, head of sales, secret shopper consultant, equity-track team member, or future W-2 employee. Nothing is promised, but the door is open."),

  // Section 4
  H2("4. Compensation Structure"),
  P("This is a 100% commission, 1099 independent contractor role. There is no base salary, no draw, and no minimum guaranteed payout. In exchange, the commission rate is set at a level that rewards real production rather than warming a seat."),

  H3("Commission Rates"),
  new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [3600, 2160, 3600],
    rows: [
      new TableRow({
        tableHeader: true,
        children: [
          tCell("Program", { width: 3600, bold: true, color: "FFFFFF", shading: BRAND_DARK }),
          tCell("Commission", { width: 2160, bold: true, color: "FFFFFF", shading: BRAND_DARK }),
          tCell("Notes", { width: 3600, bold: true, color: "FFFFFF", shading: BRAND_DARK }),
        ]
      }),
      new TableRow({
        children: [
          tCell("90-Day Growth Engine ($9,000 high-ticket)", { width: 3600 }),
          tCell("10% ($900 per close)", { width: 2160, bold: true }),
          tCell("Paid on collected revenue, not signed contracts", { width: 3600 }),
        ]
      }),
      new TableRow({
        children: [
          tCell("Future mid-tier program (interior design partnership, est. $1,200 to $1,800)", { width: 3600, shading: BRAND_LIGHT }),
          tCell("10%", { width: 2160, bold: true, shading: BRAND_LIGHT }),
          tCell("Rate confirmed at program launch", { width: 3600, shading: BRAND_LIGHT }),
        ]
      }),
      new TableRow({
        children: [
          tCell("Secret Shopper engagements ($2,500 plus travel)", { width: 3600 }),
          tCell("10% of service fee", { width: 2160, bold: true }),
          tCell("Travel and lodging billed separately to client and not commissionable", { width: 3600 }),
        ]
      }),
      new TableRow({
        children: [
          tCell("Future programs, courses, memberships, and offers", { width: 3600, shading: BRAND_LIGHT }),
          tCell("10% baseline", { width: 2160, bold: true, shading: BRAND_LIGHT }),
          tCell("Adjusted rates, if any, agreed in writing before launch", { width: 3600, shading: BRAND_LIGHT }),
        ]
      }),
    ]
  }),

  H3("Payment Terms"),
  Bullet("Commissions are earned only on cleared, non-refunded payments received by The Luxora Collective."),
  Bullet("Commissions are paid out twice monthly, on the 15th and the last business day of each month, for revenue collected in the prior pay period."),
  Bullet("If a client refunds, charges back, or is released within their guarantee window, the related commission is reversed against future payouts."),
  Bullet("Payments are issued via direct deposit, Wise, or another mutually agreed method. A W-9 is required before the first payout."),
  Bullet("As a 1099 contractor, you are responsible for your own taxes, withholdings, and any applicable self-employment obligations."),

  H3("Future W-2 Conversion"),
  P("This role is structured as 1099 today with the explicit option to convert to W-2 employment in the future, contingent on company stage, revenue, and mutual interest. A future W-2 conversion would include a re-negotiated compensation structure (typically a base plus commission blend), benefits where available, and a formal employment agreement to replace this contractor agreement."),

  // Section 5
  H2("5. Sales KPIs and Performance Standards"),
  P("KPIs exist so both sides know how the role is performing. They are not designed as traps. They are how we identify what is working, what is not, and where you need more support, more leads, or more coaching. KPIs will be reviewed every two weeks during a standing check-in with leadership."),

  H3("Activity KPIs (controllable inputs)"),
  Bullet("Show rate on booked discovery calls: minimum 70%."),
  Bullet("Same-day or next-business-day follow-up on every call that does not close on the first conversation."),
  Bullet("100% of calls and outcomes logged in GoHighLevel within 24 hours, including call notes, objection log, and next-step disposition."),
  Bullet("All scheduled calls accepted, confirmed, and reminder sequences verified in GHL before the call."),

  H3("Outcome KPIs (results)"),
  Bullet("Close rate on discovery calls: target 40% to 50% on qualified inbound. Bethany is currently closing roughly 50% as a benchmark."),
  Bullet("Average sales cycle: target 7 days or less from first call to closed deal on inbound."),
  Bullet("Monthly closed revenue: minimum threshold to be set jointly after the first 60 days of ramp, once baseline data is established."),
  Bullet("Client quality: closes that complete onboarding and remain in good standing through their first 30 days. We do not reward sales that ghost or churn out of the gate."),

  H3("Quality and Brand KPIs"),
  Bullet("Zero complaints related to misrepresentation, high-pressure tactics, or off-brand conduct on calls."),
  Bullet("Adherence to the approved sales script and feminine funnel framework."),
  Bullet("Positive feedback signal from clients during onboarding (\"the sales experience matched the actual product\")."),

  H3("Performance Reviews and Adjustments"),
  Bullet("First review at 30 days: ramp check, coaching, and script refinement."),
  Bullet("Second review at 60 days: KPI baseline locked in based on observed lead flow and close rates."),
  Bullet("Quarterly reviews thereafter: KPIs recalibrated, commission opportunities revisited, role expansion discussed."),
  Bullet("Bonus structures, accelerators, and SPIFs may be introduced at leadership\u2019s discretion. Any such bonuses will be confirmed in writing before they apply."),

  // Section 6
  H2("6. Culture and Working Style"),
  P("Luxora is being built deliberately. We took longer than most to lay our foundation because we wanted the company to be strong by the time it scaled. We are now in that scaling moment, and culture is the thing we protect most carefully as we grow."),
  Bullet("We are a team, not a roster. Everyone contributes outside their title when the moment calls for it. In return, no one is asked to grind for the sake of grinding."),
  Bullet("There is life outside of work. Block your calendar when you need to. Protect your evenings, your weekends, and your training, family, and faith commitments. We do the same."),
  Bullet("We are direct, warm, and unapologetic about quality. We do not tolerate dishonesty toward clients, teammates, or ourselves."),
  Bullet("We are transparent about money. If you ever want to know how a number was calculated, ask. We will show you."),
  Bullet("We are open to ideas. If you see a better way to run a call, a follow-up, or a process, bring it. We do not always say yes, but we always listen."),
  Bullet("We celebrate wins out loud. Closes, milestones, client breakthroughs, and personal wins all get acknowledged."),
  P("Our long-term vision includes scaling Luxora to a size and structure that could lead to acquisition. Team members who are with us through that journey will be remembered and rewarded. That is not a promise of equity, but it is a promise of loyalty in both directions."),

  // Section 7
  H2("7. Exclusivity and Non-Compete Summary"),
  P("Because of the proprietary nature of our frameworks, scripts, prospect lists, ad strategies, and partner ecosystem, this role carries an exclusivity and non-compete provision that will be fully detailed in the accompanying Independent Contractor Agreement. In summary:"),
  Bullet("During the term of your engagement with The Luxora Collective, you may not work for, consult with, refer business to, or otherwise represent any other aesthetic, medspa, or beauty industry growth, marketing, consulting, or coaching agency that competes with Luxora\u2019s services."),
  Bullet("You may continue to hold non-competing employment, side projects, and personal interests outside the aesthetic and medspa growth-services industry without restriction."),
  Bullet("For 12 months following the end of your engagement, you may not directly solicit Luxora clients, prospects in our active pipeline, or named team partners (including but not limited to Aesthetic Injector Academy, Youthtopia MedSpa, and current strategic partners) for competing services."),
  Bullet("You may not retain, copy, distribute, or repurpose Luxora\u2019s scripts, frameworks, playbooks, deliverables, prospect data, ad creative, or CRM contents for any purpose outside this role."),
  P("These provisions will be drafted to be reasonable in scope, geography, and duration as required under Tennessee law, and the binding language lives in the Independent Contractor Agreement."),

  // Section 8
  H2("8. Schedule, Availability, and Communication"),
  Bullet("Calendar availability: open Monday through Saturday for inbound sales calls during standard business hours across U.S. time zones. Personal blocks (workouts, sports, faith commitments) are respected and expected."),
  Bullet("No 3 a.m. emergencies. We do not text, call, or message after hours unless something is genuinely on fire. The same courtesy applies to you."),
  Bullet("Internal communication runs through Slack. Client communication runs through GoHighLevel. Personal phone numbers stay personal."),
  Bullet("Time zones: leadership operates on Central time. Other team members operate on Eastern, Pacific, and South Africa time. Meeting times are coordinated through our executive assistant, Aanchal."),

  // Section 9
  H2("9. Onboarding Plan (First 30 Days)"),
  Bullet("Week 1: Shadow Bethany on live discovery calls. Full review of sales script, Revenue Leak Audit, Market Blueprint, and program deliverables. Access provisioned for GHL, Slack, market intelligence tool, and document library."),
  Bullet("Week 2: Co-pilot calls with Bethany. Begin handling follow-up touches, second conversations, and assigned outbound from the prospect tool. Reference calls completed and contractor agreement signed."),
  Bullet("Week 3: Run solo discovery calls on assigned leads with post-call review. First commissions begin landing as deals close."),
  Bullet("Week 4: Full ownership of inbound sales calendar with weekly review cadence. First 30-day performance check with leadership."),

  // Section 10
  H2("10. Next Steps"),
  Bullet("Provide professional references (prior sales leadership and most recent medspa employer)."),
  Bullet("Receive and review the Independent Contractor Agreement that accompanies this outline."),
  Bullet("Sign the contractor agreement, complete a W-9, and confirm payment method."),
  Bullet("Schedule the kickoff session with Bethany to begin shadowing and onboarding."),
  P("We are excited about the possibility of building this with you, William. The product sells, the leads are coming, the systems are in place, and the culture is real. The only thing missing is the right person on the phone, and we believe that could be you."),

  new Paragraph({
    spacing: { before: 600, after: 200 },
    children: [new TextRun({ text: "Issued in good faith and in partnership,", italics: true, size: 22 })]
  }),
  new Paragraph({
    spacing: { before: 200, after: 60 },
    children: [new TextRun({ text: "Bethany [Last Name]", bold: true, size: 22 })]
  }),
  new Paragraph({
    spacing: { after: 200 },
    children: [new TextRun({ text: "Co-Founder & CEO, The Luxora Collective", size: 20, color: "555555" })]
  }),
  new Paragraph({
    spacing: { before: 200, after: 60 },
    children: [new TextRun({ text: "Eric [Last Name]", bold: true, size: 22 })]
  }),
  new Paragraph({
    spacing: { after: 200 },
    children: [new TextRun({ text: "Co-Founder & CFO, The Luxora Collective", size: 20, color: "555555" })]
  }),
];

const doc = new Document({
  creator: "The Luxora Collective",
  title: "Sales Partner Role Outline",
  styles: {
    default: { document: { run: { font: "Calibri", size: 22 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 36, bold: true, font: "Calibri", color: BRAND_DARK },
        paragraph: { spacing: { before: 320, after: 200 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 28, bold: true, font: "Calibri", color: BRAND_GOLD },
        paragraph: { spacing: { before: 280, after: 140 }, outlineLevel: 1,
          border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: BRAND_GOLD, space: 4 } } } },
      { id: "Heading3", name: "Heading 3", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 24, bold: true, font: "Calibri", color: BRAND_DARK },
        paragraph: { spacing: { before: 200, after: 100 }, outlineLevel: 2 } },
    ]
  },
  numbering: {
    config: [
      { reference: "bullets",
        levels: [
          { level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
            style: { paragraph: { indent: { left: 720, hanging: 360 } } } },
          { level: 1, format: LevelFormat.BULLET, text: "\u25E6", alignment: AlignmentType.LEFT,
            style: { paragraph: { indent: { left: 1440, hanging: 360 } } } },
        ] },
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    headers: {
      default: new Header({
        children: [new Paragraph({
          alignment: AlignmentType.RIGHT,
          children: [new TextRun({ text: "THE LUXORA COLLECTIVE", size: 16, color: BRAND_GOLD, characterSpacing: 60 })]
        })]
      })
    },
    footers: {
      default: new Footer({
        children: [new Paragraph({
          alignment: AlignmentType.CENTER,
          children: [
            new TextRun({ text: "Sales Partner Role Outline  |  Confidential  |  Page ", size: 16, color: "888888" }),
            new TextRun({ children: [PageNumber.CURRENT], size: 16, color: "888888" })
          ]
        })]
      })
    },
    children: [...cover, ...body]
  }]
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync("/home/claude/luxora_docs/Luxora_Sales_Partner_Role_Outline.docx", buf);
  console.log("Role outline created.");
});

