const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
        AlignmentType, LevelFormat, HeadingLevel, BorderStyle, WidthType,
        ShadingType, PageNumber, Header, Footer } = require('docx');
const fs = require('fs');

const BRAND_GOLD = "B08D57";
const BRAND_DARK = "1F1F1F";
const BRAND_LIGHT = "F5F1EA";
const BORDER_GREY = "CCCCCC";

const border = { style: BorderStyle.SINGLE, size: 1, color: BORDER_GREY };
const borders = { top: border, bottom: border, left: border, right: border };

const P = (text, opts = {}) => new Paragraph({
  spacing: { before: 80, after: 80, line: 300 },
  alignment: opts.center ? AlignmentType.CENTER : AlignmentType.JUSTIFIED,
  children: [new TextRun({ text, bold: opts.bold, italics: opts.italics, size: opts.size || 22, color: opts.color })]
});

const Section = (number, title) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  spacing: { before: 320, after: 140 },
  children: [
    new TextRun({ text: `${number}. `, bold: true, size: 26, color: BRAND_GOLD }),
    new TextRun({ text: title.toUpperCase(), bold: true, size: 24, color: BRAND_DARK, characterSpacing: 30 })
  ]
});

const Sub = (label, body) => new Paragraph({
  spacing: { before: 100, after: 80, line: 300 },
  alignment: AlignmentType.JUSTIFIED,
  children: [
    new TextRun({ text: `${label}  `, bold: true, size: 22 }),
    new TextRun({ text: body, size: 22 })
  ]
});

const Bullet = (text, level = 0) => new Paragraph({
  numbering: { reference: "agbullets", level },
  spacing: { before: 40, after: 40, line: 290 },
  children: [new TextRun({ text, size: 22 })]
});

const Lettered = (label, text) => new Paragraph({
  spacing: { before: 60, after: 60, line: 290 },
  indent: { left: 720, hanging: 360 },
  children: [
    new TextRun({ text: `(${label})  `, bold: true, size: 22 }),
    new TextRun({ text, size: 22 })
  ]
});

const SignBlock = (party, fields) => {
  return [
    new Paragraph({
      spacing: { before: 240, after: 120 },
      children: [new TextRun({ text: party, bold: true, size: 22, color: BRAND_DARK })]
    }),
    ...fields.map(f => new Paragraph({
      spacing: { before: 200, after: 40 },
      children: [
        new TextRun({ text: `${f}: `, bold: true, size: 22 }),
        new TextRun({ text: "_______________________________________________", size: 22, color: "888888" })
      ]
    }))
  ];
};

// ---------- COVER ----------
const cover = [
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 2400, after: 200 },
    children: [new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, size: 32, color: BRAND_GOLD, characterSpacing: 80 })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 1600 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: BRAND_GOLD, space: 8 } },
    children: [new TextRun({ text: "Independent Contractor Agreement", italics: true, size: 24, color: BRAND_DARK })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 600, after: 100 },
    children: [new TextRun({ text: "Sales Partner, 1099 Engagement", size: 26, bold: true })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 1600 },
    children: [new TextRun({ text: "With Future Option to Convert to W-2 Employment", size: 22, italics: true, color: "555555" })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 400, after: 100 },
    children: [new TextRun({ text: "Between:", size: 20, color: "777777" })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 60 },
    children: [new TextRun({ text: "The Luxora Collective, LLC", size: 24, bold: true })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 400 },
    children: [new TextRun({ text: "and", size: 22, italics: true, color: "777777" })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 600 },
    children: [new TextRun({ text: "William [Last Name]", size: 24, bold: true })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 800, after: 60 },
    children: [new TextRun({ text: "Effective Date: ____________________, 2026", size: 22, color: "555555" })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 1200 },
    children: [new TextRun({ text: "DRAFT FOR ATTORNEY REVIEW", size: 18, bold: true, color: BRAND_GOLD, characterSpacing: 40 })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 80 },
    children: [new TextRun({ text: "Review and finalize with Tennessee-licensed counsel before execution.", size: 18, italics: true, color: "777777" })]
  }),
  new Paragraph({ children: [new TextRun({ text: "", break: 1 })], pageBreakBefore: true })
];

// ---------- BODY ----------
const body = [
  new Paragraph({
    heading: HeadingLevel.HEADING_1,
    children: [new TextRun({ text: "Independent Contractor Agreement" })],
    spacing: { after: 240 }
  }),
  P("This Independent Contractor Agreement (the \"Agreement\") is entered into as of the Effective Date set forth on the cover page by and between The Luxora Collective, LLC, a limited liability company organized under the laws of the State of Tennessee, with its principal address at [Insert Address] (the \"Company\"), and William [Last Name], an individual residing at [Insert Address] (the \"Contractor\"). The Company and the Contractor are referred to collectively as the \"Parties\" and individually as a \"Party.\""),
  P("In consideration of the mutual covenants set forth below, the Parties agree as follows:"),

  Section("1", "Engagement and Role"),
  Sub("1.1 Engagement.", "The Company engages the Contractor, and the Contractor accepts the engagement, to provide sales services as further described in Section 2 of this Agreement and in the Sales Partner Role Outline issued by the Company (the \"Role Outline\"), which is incorporated by reference. In the event of any conflict between this Agreement and the Role Outline, this Agreement controls."),
  Sub("1.2 Title.", "The Contractor\u2019s title is Sales Partner."),
  Sub("1.3 Independent Contractor Status.", "The Contractor is engaged as an independent contractor and not as an employee, partner, joint venturer, or agent of the Company. Nothing in this Agreement creates an employer-employee, partnership, or fiduciary relationship. The Contractor is responsible for all federal, state, and local income taxes, self-employment taxes, and any other taxes or withholdings arising from compensation paid under this Agreement. The Company will issue a Form 1099-NEC to the Contractor for each calendar year in which compensation is paid, as required by law."),
  Sub("1.4 No Benefits.", "As an independent contractor, the Contractor is not eligible for any benefits the Company may provide to its employees, including health insurance, retirement plans, paid time off, workers\u2019 compensation, or unemployment insurance."),
  Sub("1.5 Future W-2 Conversion.", "The Parties acknowledge that, subject to mutual agreement and the Company\u2019s business needs, the Contractor\u2019s engagement may be converted to W-2 employment in the future. Any such conversion will require a separate written employment agreement that supersedes this Agreement with respect to the employment relationship. Until any such conversion is executed in writing, the Contractor remains an independent contractor under this Agreement."),

  Section("2", "Services"),
  Sub("2.1 Scope.", "The Contractor will provide the following services (the \"Services\"):"),
  Bullet("Conduct discovery, sales, and follow-up calls with prospects assigned by the Company."),
  Bullet("Use the Company\u2019s approved sales scripts, frameworks (including the Revenue Leak Audit and Market Blueprint), and methodology."),
  Bullet("Convert qualified prospects into paying clients of the 90-Day Growth Engine and any other Company programs offered now or in the future."),
  Bullet("Maintain accurate records of all sales activity in the Company\u2019s CRM (currently GoHighLevel) within 24 hours of each interaction."),
  Bullet("Perform reasonable sales-adjacent tasks at the Company\u2019s request, including follow-up touches, secondary sales conversations, partner outreach, and light onboarding handoff support."),
  Sub("2.2 Standards.", "The Contractor will perform the Services in a professional, ethical manner, in accordance with the Company\u2019s brand standards, applicable law, and the cultural standards described in the Role Outline. The Contractor will not engage in high-pressure sales tactics, misrepresentation, or off-brand conduct."),
  Sub("2.3 Means and Manner.", "Subject to the standards above, the Contractor controls the means and manner by which the Services are performed, including the Contractor\u2019s schedule, work location, and tools, except where call schedules, client communications, and CRM logging require coordination with the Company\u2019s systems."),

  Section("3", "Term and Termination"),
  Sub("3.1 Term.", "This Agreement begins on the Effective Date and continues until terminated in accordance with this Section 3."),
  Sub("3.2 Termination Without Cause.", "Either Party may terminate this Agreement, with or without reason, upon fourteen (14) days\u2019 written notice to the other Party."),
  Sub("3.3 Termination for Cause.", "The Company may terminate this Agreement immediately, without notice, upon any of the following:"),
  Lettered("a", "the Contractor\u2019s material breach of this Agreement, including but not limited to breach of confidentiality, non-compete, or non-solicitation obligations;"),
  Lettered("b", "the Contractor\u2019s engagement in fraud, dishonesty, gross negligence, or willful misconduct;"),
  Lettered("c", "the Contractor\u2019s misrepresentation of the Company\u2019s services to any prospect, client, or third party;"),
  Lettered("d", "the Contractor\u2019s sustained failure to meet the performance standards described in Section 5 after written notice and a reasonable opportunity to cure; or"),
  Lettered("e", "any conduct that materially damages the Company\u2019s reputation, client relationships, or business interests."),
  Sub("3.4 Effect of Termination.", "Upon termination for any reason, the Contractor will (a) immediately cease holding themselves out as associated with the Company, (b) return or destroy all Confidential Information and Company materials in their possession, (c) cease all use of Company-issued accounts, scripts, frameworks, prospect data, and CRM access, and (d) cooperate in the orderly transition of any in-process sales conversations. Sections 6 through 12 survive termination of this Agreement."),

  Section("4", "Compensation"),
