const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
        AlignmentType, LevelFormat, HeadingLevel, BorderStyle, WidthType,
        ShadingType, PageNumber, Header, Footer } = require('docx');
const fs = require('fs');

const BRAND_GOLD = "B08D57";
const BRAND_DARK = "1F1F1F";
const BRAND_LIGHT = "F5F1EA";
const BORDER_GREY = "CCCCCC";

const border = { style: BorderStyle.SINGLE, size: 1, color: BORDER_GREY };
const borders = { top: border, bottom: border, left: border, right: border };

const P = (text, opts = {}) => new Paragraph({
  spacing: { before: 100, after: 100, line: 320 },
  children: [new TextRun({ text, bold: opts.bold, italics: opts.italics, size: opts.size || 22, color: opts.color })]
});

const H2 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  children: [new TextRun({ text })],
  spacing: { before: 320, after: 140 }
});

const Bullet = (text) => new Paragraph({
  numbering: { reference: "bullets", level: 0 },
  spacing: { before: 60, after: 60, line: 300 },
  children: [new TextRun({ text, size: 22 })]
});

const tCell = (text, opts = {}) => new TableCell({
  borders,
  width: { size: opts.width || 4680, type: WidthType.DXA },
  shading: opts.shading ? { fill: opts.shading, type: ShadingType.CLEAR } : undefined,
  margins: { top: 100, bottom: 100, left: 140, right: 140 },
  children: [new Paragraph({
    children: [new TextRun({ text, bold: opts.bold, color: opts.color, size: opts.size || 22 })]
  })]
});

// COVER
const cover = [
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 2400, after: 200 },
    children: [new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, size: 32, color: BRAND_GOLD, characterSpacing: 80 })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 1600 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: BRAND_GOLD, space: 8 } },
    children: [new TextRun({ text: "What This Role Looks Like", italics: true, size: 24, color: BRAND_DARK })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 600, after: 100 },
    children: [new TextRun({ text: "A Plain-English Overview of Our Sales Role", size: 26, bold: true })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 1600 },
    children: [new TextRun({ text: "What you do, what you make, what we expect", size: 22, italics: true, color: "555555" })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 1200 },
    children: [new TextRun({ text: "theluxoracollective.co", size: 20, color: BRAND_GOLD, italics: true })]
  }),
  new Paragraph({ children: [new TextRun({ text: "", break: 1 })], pageBreakBefore: true })
];

// BODY
const body = [
  new Paragraph({
    heading: HeadingLevel.HEADING_1,
    children: [new TextRun({ text: "Hey, glad you\u2019re here." })],
    spacing: { after: 200 }
  }),
  P("This is the no-fluff version of what it looks like to sell for The Luxora Collective. We\u2019ll walk you through what we do, who we sell to, what you\u2019d actually be doing day to day, how you get paid, and what we expect from you. If after reading this you\u2019re still excited, we\u2019ll send over the formal contract and get you onboarded."),

  H2("Who We Are"),
  P("The Luxora Collective is a premium growth partner for independent medspa owners doing between $500K and $2M a year. We help them stop leaking revenue, install the right systems, train their staff to actually sell, and grow without the owner having to be in every transaction."),
  P("Our flagship program is the 90-Day Growth Engine. It sells for $9,000 and includes a Revenue Leak Audit, a full Market Blueprint, and 90 days of done-with-you implementation."),
  P("We also offer secret shopper engagements, partnership programs, and we\u2019re building out lower-ticket and membership offers. The product mix will keep growing, and you\u2019ll sell across all of it."),

  H2("Who You\u2019re Selling To"),
  P("Independent medspa owners. Mostly women. Most are running good businesses but feel stuck, overworked, and frustrated that they can\u2019t scale without burning out. Our calls are emotional, honest, and warm. We don\u2019t use fake urgency. We don\u2019t pressure people. We meet them where they are and show them a path forward."),
  P("If they\u2019re a fit, they say yes pretty quickly. The product genuinely sells itself when you let the conversation breathe."),

  H2("What You\u2019d Actually Be Doing"),
  Bullet("Taking inbound discovery calls from leads our marketing team brings in (Meta ads, organic content, partnerships, and our internal prospecting tool)."),
  Bullet("Running the call using our existing script and framework. We\u2019ll train you on it. You\u2019ll shadow Bethany first."),
  Bullet("Walking prospects through the Revenue Leak Audit live on the call, then transitioning into the close."),
  Bullet("Logging your calls and notes in our CRM so we all stay on the same page."),
  Bullet("Following up with people who didn\u2019t close on the first call."),
  Bullet("If your calendar has open space, helping with sales-adjacent tasks like outbound to the prospect list, partner outreach, or light onboarding handoffs. Never tech work. Never anything outside sales."),

  H2("How You Get Paid"),
  P("This is a 100% commission role. No base, no draw. In exchange, the rate is real, and the leads are real."),

  new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [4680, 4680],
    rows: [
      new TableRow({
        tableHeader: true,
        children: [
          tCell("What You Sell", { bold: true, color: "FFFFFF", shading: BRAND_DARK }),
          tCell("What You Make", { bold: true, color: "FFFFFF", shading: BRAND_DARK }),
        ]
      }),
      new TableRow({
        children: [
          tCell("90-Day Growth Engine ($9,000)"),
          tCell("$900 per closed deal (10%)", { bold: true }),
        ]
      }),
      new TableRow({
        children: [
          tCell("Future mid-tier programs (estimated $1,200 to $1,800)", { shading: BRAND_LIGHT }),
          tCell("10% of the sale", { bold: true, shading: BRAND_LIGHT }),
        ]
      }),
      new TableRow({
        children: [
          tCell("Secret Shopper engagements ($2,500 plus travel)"),
          tCell("10% of the service fee", { bold: true }),
        ]
      }),
      new TableRow({
        children: [
          tCell("Anything new we launch (courses, memberships, programs)", { shading: BRAND_LIGHT }),
