const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
        AlignmentType, LevelFormat, HeadingLevel, BorderStyle, WidthType,
        ShadingType, PageNumber, Header, Footer } = require('docx');
const fs = require('fs');

const BRAND_GOLD = "B08D57";
const BRAND_DARK = "1F1F1F";
const BRAND_LIGHT = "F5F1EA";
const BORDER_GREY = "CCCCCC";

const border = { style: BorderStyle.SINGLE, size: 1, color: BORDER_GREY };
const borders = { top: border, bottom: border, left: border, right: border };

// Compact paragraph
const P = (text, opts = {}) => new Paragraph({
  spacing: { before: 40, after: 40, line: 260 },
  alignment: opts.center ? AlignmentType.CENTER : AlignmentType.LEFT,
  children: [new TextRun({ text, bold: opts.bold, italics: opts.italics, size: opts.size || 18, color: opts.color })]
});

// Compact bullet
const Bullet = (text) => new Paragraph({
  numbering: { reference: "sopbullets", level: 0 },
  spacing: { before: 20, after: 20, line: 250 },
  children: [new TextRun({ text, size: 18 })]
});

// Step header (numbered phase)
const Step = (number, title, time) => new Paragraph({
  spacing: { before: 140, after: 60 },
  children: [
    new TextRun({ text: `STEP ${number}  `, bold: true, size: 20, color: BRAND_GOLD, characterSpacing: 30 }),
    new TextRun({ text: title.toUpperCase(), bold: true, size: 20, color: BRAND_DARK, characterSpacing: 20 }),
    new TextRun({ text: `   ${time}`, italics: true, size: 16, color: "777777" }),
  ]
});

// Cell
const tCell = (text, opts = {}) => new TableCell({
  borders,
  width: { size: opts.width, type: WidthType.DXA },
  shading: opts.shading ? { fill: opts.shading, type: ShadingType.CLEAR } : undefined,
  margins: { top: 60, bottom: 60, left: 100, right: 100 },
  children: [new Paragraph({
    spacing: { before: 0, after: 0 },
    children: [new TextRun({ text, bold: opts.bold, color: opts.color, size: opts.size || 16 })]
  })]
});

const body = [
  // ---- Title block ----
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 0, after: 40 },
    children: [new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, size: 22, color: BRAND_GOLD, characterSpacing: 80 })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 60 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: BRAND_GOLD, space: 4 } },
    children: [new TextRun({ text: "Sales Call SOP", italics: true, size: 18, color: BRAND_DARK })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 100, after: 40 },
    children: [new TextRun({ text: "Discovery Call: Open, Audit, Ask, Close", bold: true, size: 26, color: BRAND_DARK })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { after: 120 },
    children: [new TextRun({ text: "One-page playbook for every Luxora discovery call. 30 to 60 minutes total.", italics: true, size: 16, color: "555555" })]
  }),

  // ---- Core principles bar ----
  new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [3120, 3120, 3120],
    rows: [
      new TableRow({
        children: [
          tCell("SLOW DOWN. The first half builds trust, not pressure.", { width: 3120, shading: BRAND_LIGHT, bold: true, size: 16 }),
          tCell("MIRROR HER WORDS. Not summaries. Her exact language.", { width: 3120, shading: BRAND_LIGHT, bold: true, size: 16 }),
          tCell("LET SILENCE WORK. After the price, stop talking.", { width: 3120, shading: BRAND_LIGHT, bold: true, size: 16 }),
        ]
      })
    ]
  }),

  // ---- STEP 1: OPEN ----
  Step("1", "Open the Call", "60 to 90 seconds"),
  Bullet("Greet warmly. Quick weather/location small talk to humanize the call. Do not dwell."),
  Bullet("Set the frame: \"I reviewed everything you shared before the call. My goal is to genuinely understand what's going on, where you feel stuck, and whether there's an opportunity for us to help. If there is, I'll walk you through what that looks like. If not, I'll point you in the right direction either way. Sound fair?\""),
  Bullet("Hand the mic over: \"I want to hear it directly from you. What's going on in your business right now that made you reach out?\""),

  // ---- STEP 2: DISCOVERY VIA REVENUE LEAK AUDIT ----
  Step("2", "Discover Through the Revenue Leak Audit", "10 to 15 minutes"),
  P("After she has shared her story in her own words, transition into the Revenue Leak Audit. The audit IS the discovery. It surfaces real numbers, exposes hidden gaps, and gives her a tangible reason to keep listening. Frame it as a gift, not a quiz.", { italics: true }),
  P("Transition line: \"I have a little revenue leak audit I can walk you through. It takes about five minutes and it'll show us exactly where money is leaking in your business right now. Can I share my screen?\"", { bold: true }),

  P("Walk her through the audit and capture answers in the tool:", { bold: true }),
  Bullet("Annual revenue and current monthly average."),
  Bullet("Monthly lead flow (organic, paid, walk-in, referral) and predictability."),
  Bullet("Speed to lead and number of follow-up touches per inquiry."),
  Bullet("CRM and automation: manual or automated, how many workflows running."),
  Bullet("Booking conversion rate, no-show rate, deposit policy."),
  Bullet("Consultation structure: who runs them, scripted or freelance, close rate."),
  Bullet("Average first transaction value, package versus single treatment mix, financing usage."),
  Bullet("Membership count and percentage of total client base."),
  Bullet("Skincare retail as a percentage of revenue."),
